def transform(grid):
    out = [row[:] for row in grid]
    cells4 = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4]
    cells6 = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 6]
    r0 = min(r for r, c in cells4)
    r1 = max(r for r, c in cells4)
    c0 = min(c for r, c in cells4)
    c1 = max(c for r, c in cells4)
    mr0 = min(r for r, c in cells6)
    mr1 = max(r for r, c in cells6)
    mc0 = min(c for r, c in cells6)
    mc1 = max(c for r, c in cells6)
    for r, c in cells6:
        out[r][c] = 0
    top_count = sum(1 for r, c in cells6 if r == mr0)
    bottom_count = sum(1 for r, c in cells6 if r == mr1)
    if top_count > bottom_count:
        for r, c in cells4:
            out[r][c1 + 1 + (c1 - c)] = 4
    elif bottom_count > top_count:
        for r, c in cells4:
            out[r][c0 - 1 - (c - c0)] = 4
    else:
        marker_center = (mc0 + mc1) / 2
        if c0 <= marker_center <= c1:
            for r, c in cells4:
                out[r1 + 1 + (r1 - r)][c] = 4
        else:
            for r, c in cells4:
                out[r0 - 1 - (r - r0)][c] = 4
    return out
